<?php
require_once __DIR__ . '/../includes/auth.php';
require_customer();
$customerId = (int) current_user()['customer_id'];
$upcoming = all_rows("SELECT a.*, s.service_name, CONCAT(st.first_name, ' ', st.last_name) staff_name FROM appointments a JOIN services s ON s.service_id = a.service_id JOIN staff st ON st.staff_id = a.staff_id WHERE a.customer_id = ? AND a.status = 'Scheduled' AND a.appointment_date >= CURDATE() ORDER BY a.appointment_date, a.appointment_time LIMIT 5", [$customerId]);
$history = all_rows("SELECT a.*, s.service_name, CONCAT(st.first_name, ' ', st.last_name) staff_name FROM appointments a JOIN services s ON s.service_id = a.service_id JOIN staff st ON st.staff_id = a.staff_id WHERE a.customer_id = ? ORDER BY a.appointment_date DESC, a.appointment_time DESC LIMIT 5", [$customerId]);
$serviceCount = (int) scalar("SELECT COUNT(*) FROM services WHERE status = 'Active'");
$page_title = 'My Customer Portal'; $customer_active = 'home'; require __DIR__ . '/../includes/customer_header.php';
?>
