<div class="row g-3 mb-4"><div class="col-md-4"><div class="customer-stat"><span class="customer-stat-icon blue"><i class="bi bi-calendar-heart"></i></span><div><strong><?= count($upcoming) ?></strong><small>Upcoming visits</small></div></div></div><div class="col-md-4"><div class="customer-stat"><span class="customer-stat-icon rose"><i class="bi bi-stars"></i></span><div><strong><?= $serviceCount ?></strong><small>Services available</small></div></div></div><div class="col-md-4"><div class="customer-stat"><span class="customer-stat-icon gold"><i class="bi bi-clock-history"></i></span><div><strong><?= scalar('SELECT COUNT(*) FROM appointments WHERE customer_id = ?', [$customerId]) ?></strong><small>Total visits</small></div></div></div></div>
